const i = $input.first().json || {};
const h = i.headers || {};
const b = i.body || i;
const token = String($env.N8N_CONEXAO_SERES_JORNADA_WEBHOOK_TOKEN || '').trim();
if (!token) throw new Error('N8N_CONEXAO_SERES_JORNADA_WEBHOOK_TOKEN não configurado.');
const authorization = String(h.authorization || h.Authorization || '').trim();
if (authorization !== `Bearer ${token}`) throw new Error('Unauthorized');
const eventType = String(b.eventType || '').trim();
if (!['jornada_yoga_registration_created','jornada_yoga_payment_paid'].includes(eventType)) {
  throw new Error('Evento inválido para a Jornada Yoga.');
}
if (String(b.eventId || '') !== 'jornada-yoga-2026') throw new Error('eventId inválido.');
const paymentId = String(b.paymentId || '').trim();
const customerName = String(b.customerName || '').trim();
const customerEmail = String(b.customerEmail || '').trim().toLowerCase();
const customerWhatsapp = String(b.customerWhatsapp || '').replace(/\D/g,'');
if (!paymentId || !customerName || !customerEmail) throw new Error('Dados obrigatórios ausentes.');
if (eventType === 'jornada_yoga_registration_created' && !String(b.invoiceUrl || '').trim()) {
  throw new Error('Link de pagamento ausente no cadastro da Jornada.');
}
return [{
  json:{
    ...b,
    eventType,
    paymentId,
    customerName,
    customerEmail,
    customerWhatsapp,
    messageApprovalStatus:'APPROVED'
  }
}];

const i = $input.first().json || {};
const paymentId = String(i.paymentId || '').trim();
const customerName = String(i.customerName || '').trim();
const customerEmail = String(i.customerEmail || '').trim().toLowerCase();
const rawWhatsapp = String(i.customerWhatsapp || '').trim();
const status = String(i.status || '').trim().toUpperCase();
const value = Number(i.value);

if (!paymentId) throw new Error('paymentId não informado.');
if (!customerName) throw new Error('customerName não informado.');
if (!customerEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(customerEmail)) throw new Error('customerEmail inválido ou não informado.');
if (!['CONFIRMED','RECEIVED','RECEIVED_IN_CASH'].includes(status)) throw new Error('status inválido para confirmação da Jornada.');
if (!Number.isFinite(value) || Math.abs(value - 297) > 0.001) throw new Error('value inválido para a Jornada.');

const digits = rawWhatsapp.replace(/\D/g, '');
let whatsappNumber = '';
if (digits.length === 13 && digits.startsWith('55')) whatsappNumber = '+' + digits;
else if (digits.length === 11) whatsappNumber = '+55' + digits;
else throw new Error('WhatsApp inválido. Informe DDD + número móvel brasileiro.');

const staticData = $getWorkflowStaticData('global');
if (!staticData.jornadaYogaPaidMessages || typeof staticData.jornadaYogaPaidMessages !== 'object') staticData.jornadaYogaPaidMessages = {};
const sent = staticData.jornadaYogaPaidMessages;
const now = Date.now();
const retentionMs = 180 * 24 * 60 * 60 * 1000;
for (const [id, timestamp] of Object.entries(sent)) {
  const savedAt = Number(timestamp);
  if (!Number.isFinite(savedAt) || now - savedAt > retentionMs) delete sent[id];
}
if (sent[paymentId]) return [];
sent[paymentId] = now;

const safeName = customerName.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;');

const whatsappMessage = [
  '*Pagamento confirmado* ✅',
  '',
  'Olá, ' + customerName + '!',
  '',
  'Identificamos o pagamento da sua inscrição na *Jornada de Expansão Mental e Corporal*. Sua participação está confirmada. 💚',
  '',
  'Serão *8 encontros online*, sempre às *20h*, nas seguintes datas:',
  '',
  '📅 07, 14, 21 e 28 de outubro',
  '📅 04, 11, 18 e 25 de novembro',
  '',
  'Os encontros serão realizados pelo *Google Meet*.',
  '',
  'Você também receberá as orientações para acesso ao grupo de WhatsApp da Jornada, onde serão compartilhados os links dos encontros e demais informações importantes.',
  '',
  '📄 A nota fiscal será enviada automaticamente para o e-mail informado no cadastro.',
  '',
  'Ficamos felizes em ter você com a gente nessa Jornada. ✨',
  '',
  'Se precisar de qualquer ajuda, pode falar conosco por aqui.',
  '',
  '*Conexão Seres*'
].join('\n');

const emailSubject = 'Pagamento confirmado — sua participação na Jornada está garantida';
const emailPreheader = 'Sua inscrição na Jornada de Expansão Mental e Corporal está confirmada.';
const emailText = [
  'Olá, ' + customerName + '!',
  '',
  'Identificamos o pagamento da sua inscrição na Jornada de Expansão Mental e Corporal.',
  '',
  'Sua participação está confirmada. 💚',
  '',
  'Ao longo de 8 encontros online, vamos construir esse espaço de diálogos terapêuticos, práticas de Yoga, respiração consciente, meditação, relaxamento e autoconhecimento.',
  '',
  'Confira as informações da Jornada:',
  '',
  '📅 Datas: 07, 14, 21 e 28 de outubro; 04, 11, 18 e 25 de novembro de 2026',
  '🕗 Horário: 20h',
  '💻 Formato: online, pelo Google Meet',
  '📄 Material: conteúdo de apoio em PDF',
  '💬 Grupo de WhatsApp: espaço para integração e compartilhamento dos links e informações dos encontros',
  '',
  'Em breve, você receberá as orientações para acesso ao grupo de WhatsApp da Jornada.',
  '',
  'Nota fiscal',
  'A nota fiscal referente ao pagamento será enviada automaticamente para o e-mail informado no cadastro.',
  '',
  'Ficamos felizes em ter você com a gente nessa Jornada.',
  '',
  'Se precisar de qualquer ajuda ou tiver alguma dúvida, nossa equipe está à disposição.',
  '',
  'Um abraço,',
  'Equipe Conexão Seres'
].join('\n');

const emailHtml = '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + emailSubject + '</title></head>' +
'<body style="margin:0;padding:0;background-color:#f4f5f3;font-family:Arial,Helvetica,sans-serif;color:#333333;">' +
'<div style="display:none;font-size:1px;line-height:1px;color:#f4f5f3;max-height:0;max-width:0;opacity:0;overflow:hidden;">' + emailPreheader + '</div>' +
'<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#f4f5f3" style="width:100%;border-collapse:collapse;background-color:#f4f5f3;"><tr><td align="center" style="padding:32px 16px;">' +
'<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#ffffff" style="width:100%;max-width:640px;border-collapse:collapse;background-color:#ffffff;border:1px solid #e3e5e1;">' +
'<tr><td align="center" style="padding:26px 30px 22px;"><img src="https://conexaoseres.com.br/wp-content/uploads/2024/04/LOGOTIPO-CONEXAO-SERES-HORIZONTAL-TRANSPARENTE.png" width="320" alt="Conexão Seres" border="0" style="display:block;width:100%;max-width:320px;height:auto;margin:0 auto;border:0;"></td></tr>' +
'<tr><td bgcolor="#ff8a00" style="height:5px;line-height:5px;font-size:1px;">&nbsp;</td></tr>' +
'<tr><td style="padding:38px 40px 34px;font-size:16px;line-height:25px;color:#333333;">' +
'<h1 style="margin:0 0 24px;font-size:27px;line-height:35px;color:#005000;">Pagamento confirmado</h1>' +
'<p style="margin:0 0 20px;">Olá, <strong style="color:#594719;">' + safeName + '</strong>!</p>' +
'<p style="margin:0 0 20px;">Identificamos o pagamento da sua inscrição na <strong>Jornada de Expansão Mental e Corporal</strong>.</p>' +
'<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="margin:0 0 26px;"><tr><td width="5" bgcolor="#005000" style="width:5px;font-size:1px;">&nbsp;</td><td bgcolor="#f2f8ef" style="padding:19px 20px;font-size:17px;"><strong style="color:#005000;">Sua participação está confirmada. 💚</strong></td></tr></table>' +
'<p style="margin:0 0 24px;">Ao longo de 8 encontros online, vamos construir esse espaço de diálogos terapêuticos, práticas de Yoga, respiração consciente, meditação, relaxamento e autoconhecimento.</p>' +
'<p style="margin:0 0 12px;font-weight:bold;color:#005000;">Confira as informações da Jornada:</p>' +
'<p style="margin:0 0 24px;line-height:1.8;">📅 <strong>Datas:</strong> 07, 14, 21 e 28 de outubro; 04, 11, 18 e 25 de novembro de 2026<br>🕗 <strong>Horário:</strong> 20h<br>💻 <strong>Formato:</strong> online, pelo Google Meet<br>📄 <strong>Material:</strong> conteúdo de apoio em PDF<br>💬 <strong>Grupo de WhatsApp:</strong> espaço para integração e compartilhamento dos links e informações dos encontros</p>' +
'<p style="margin:0 0 24px;">Em breve, você receberá as orientações para acesso ao grupo de WhatsApp da Jornada.</p>' +
'<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="margin:0 0 26px;"><tr><td width="5" bgcolor="#ff8a00" style="width:5px;font-size:1px;">&nbsp;</td><td bgcolor="#fff8ef" style="padding:19px 20px;"><strong style="color:#594719;">Nota fiscal</strong><br>A nota fiscal referente ao pagamento será enviada automaticamente para o e-mail informado no cadastro.</td></tr></table>' +
'<p style="margin:0 0 20px;">Ficamos felizes em ter você com a gente nessa Jornada.</p>' +
'<p style="margin:0 0 24px;">Se precisar de qualquer ajuda ou tiver alguma dúvida, nossa equipe está à disposição.</p>' +
'<p style="margin:0;color:#594719;">Um abraço,<br><strong style="color:#005000;">Equipe Conexão Seres</strong></p>' +
'</td></tr><tr><td align="center" bgcolor="#005000" style="padding:25px 30px;font-size:12px;line-height:19px;color:#ffffff;"><strong style="font-size:14px;">Conexão Seres</strong><br>Jornada de Expansão Mental e Corporal</td></tr></table></td></tr></table></body></html>';

return [{json:{...i,whatsappNumber,whatsappMessage,emailSubject,emailPreheader,emailText,emailHtml}}];

const i = $input.first().json || {};
const paymentId = String(i.paymentId || '').trim();
const rawWhatsapp = String(i.customerWhatsapp || '').trim();
const rawUrl = String(i.invoiceUrl || '').trim();
if (!paymentId) throw new Error('paymentId não informado.');
const digits = rawWhatsapp.replace(/\D/g,'');
let whatsappNumber = '';
if (digits.length === 13 && digits.startsWith('55')) whatsappNumber = '+' + digits;
else if (digits.length === 11) whatsappNumber = '+55' + digits;
else throw new Error('WhatsApp inválido. Informe DDD + número móvel brasileiro.');
let safeUrl = false;
try { const u = new URL(rawUrl); const h = u.hostname.toLowerCase(); safeUrl = u.protocol === 'https:' && (h === 'asaas.com' || h.endsWith('.asaas.com')); } catch {}
if (!safeUrl) throw new Error('Link de pagamento inválido.');
const staticData = $getWorkflowStaticData('global');
if (!staticData.jornadaYogaRegistrationMessages || typeof staticData.jornadaYogaRegistrationMessages !== 'object') staticData.jornadaYogaRegistrationMessages = {};
const sent = staticData.jornadaYogaRegistrationMessages;
const now = Date.now();
const retentionMs = 120 * 24 * 60 * 60 * 1000;
for (const [id,timestamp] of Object.entries(sent)) { const savedAt=Number(timestamp); if (!Number.isFinite(savedAt) || now-savedAt>retentionMs) delete sent[id]; }
if (sent[paymentId]) return [];
sent[paymentId] = now;
return [{json:{...i,whatsappNumber}}];
